--region private
---刷新UI
function DreamAdventuresRewardsCell:RefreshUI(data, cellType)
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, data.rewards)
    if cellType == DreamAdventuresConstants.ScheduleRewardPopupType.PERSONAL then
        CfUtils.SetActive(self.PlayerNode, true)
        CfUtils.SetActive(self.AllPlayerNode, false)
        local pointId = DreamAdventuresMgr:GetActivityPointId()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(pointId)
        CfUtils.FillImage(self.PlayerImgicon, vo.photoPath)
        CfUtils.FillText(self.PlayerTxtNum, data.point)
    elseif cellType == DreamAdventuresConstants.ScheduleRewardPopupType.SERVER then
        CfUtils.SetActive(self.PlayerNode, false)
        CfUtils.SetActive(self.AllPlayerNode, true)
        local rewardsList = DreamAdventuresMgr:GetAllRewardsList()
        local maxPoint = rewardsList[#rewardsList].point
        CfUtils.FillText(self.AllTxtNum, string.format('%d%%', checkInt(data.point / maxPoint * 100)))
    end

    if data.status == DreamAdventuresConstants.ScheduleRewardStatus.GET then
        CfUtils.SetActive(self.FontStyleButton, true)
        CfUtils.SetActive(self.Underway, false)
        CfUtils.SetActive(self.Finish, false)
    elseif data.status == DreamAdventuresConstants.ScheduleRewardStatus.UNFINISHED then
        CfUtils.SetActive(self.FontStyleButton, false)
        CfUtils.SetActive(self.Underway, true)
        CfUtils.SetActive(self.Finish, false)
    elseif data.status == DreamAdventuresConstants.ScheduleRewardStatus.FINISHED then
        CfUtils.SetActive(self.FontStyleButton, false)
        CfUtils.SetActive(self.Underway, false)
        CfUtils.SetActive(self.Finish, true)
    end
end
--endregion private

return DreamAdventuresRewardsCell